import { StrictMode, useEffect, useState } from 'react';
import { createRoot } from 'react-dom/client';

function useLocalStorage(kunci, nilaiAwal) {
  const [nilai, setNilai] = useState(() => {
    try {
      const tersimpan = localStorage.getItem(kunci);
      return tersimpan !== null ? JSON.parse(tersimpan) : nilaiAwal;
    } catch {
      return nilaiAwal;
    }
  });

  useEffect(() => {
    localStorage.setItem(kunci, JSON.stringify(nilai));
  }, [kunci, nilai]);

  return [nilai, setNilai];
}

const FILTER = {
  semua: () => true,
  aktif: (t) => !t.selesai,
  selesai: (t) => t.selesai,
};

function PilihFilter({ nilai, onPilih }) {
  return (
    <div className="filter" role="group" aria-label="Filter tugas">
      {Object.keys(FILTER).map((nama) => (
        <button key={nama} type="button" aria-pressed={nilai === nama} onClick={() => onPilih(nama)}>
          {nama[0].toUpperCase() + nama.slice(1)}
        </button>
      ))}
    </div>
  );
}

function FormTambah({ onTambah }) {
  const [teks, setTeks] = useState('');

  function handleSubmit(e) {
    e.preventDefault();
    const bersih = teks.trim();
    if (bersih === '') return;
    onTambah(bersih);
    setTeks('');
  }

  return (
    <form className="baris" onSubmit={handleSubmit}>
      <input type="text" value={teks} onChange={(e) => setTeks(e.target.value)} placeholder="Tugas baru" />
      <button type="submit">Tambah</button>
    </form>
  );
}

function ItemTugas({ tugas, onCentang, onHapus, onUbah }) {
  const [edit, setEdit] = useState(false);
  const [teks, setTeks] = useState(tugas.teks);

  function simpan() {
    const bersih = teks.trim();
    if (bersih !== '') onUbah(tugas.id, bersih);
    else setTeks(tugas.teks);
    setEdit(false);
  }

  function handleKey(e) {
    if (e.key === 'Enter') simpan();
    if (e.key === 'Escape') {
      setTeks(tugas.teks);
      setEdit(false);
    }
  }

  if (edit) {
    return (
      <li>
        <input type="text" value={teks} onChange={(e) => setTeks(e.target.value)}
          onKeyDown={handleKey} onBlur={simpan} autoFocus aria-label="Ubah tugas" />
      </li>
    );
  }

  return (
    <li className={tugas.selesai ? 'selesai' : ''}>
      <input type="checkbox" checked={tugas.selesai} onChange={() => onCentang(tugas.id)}
        aria-label={`Tandai ${tugas.teks} selesai`} />
      <span onDoubleClick={() => setEdit(true)}>{tugas.teks}</span>
      <button onClick={() => setEdit(true)} aria-label={`Ubah ${tugas.teks}`}>✎</button>
      <button onClick={() => onHapus(tugas.id)} aria-label={`Hapus ${tugas.teks}`}>✕</button>
    </li>
  );
}

function App() {
  const [tugas, setTugas] = useLocalStorage('todolist', []);
  const [filter, setFilter] = useState('semua');

  function tambah(teks) {
    setTugas([...tugas, { id: crypto.randomUUID(), teks, selesai: false }]);
  }
  function centang(id) {
    setTugas(tugas.map((t) => (t.id === id ? { ...t, selesai: !t.selesai } : t)));
  }
  function hapus(id) {
    setTugas(tugas.filter((t) => t.id !== id));
  }
  function ubah(id, teks) {
    setTugas(tugas.map((t) => (t.id === id ? { ...t, teks } : t)));
  }
  function hapusSelesai() {
    setTugas(tugas.filter((t) => !t.selesai));
  }

  const tampil = tugas.filter(FILTER[filter]);
  const sisa = tugas.filter((t) => !t.selesai).length;

  return (
    <div className="todo">
      <h1>Todolist</h1>
      <FormTambah onTambah={tambah} />
      <ul className="daftar">
        {tampil.map((t) => (
          <ItemTugas key={t.id} tugas={t} onCentang={centang} onHapus={hapus} onUbah={ubah} />
        ))}
      </ul>
      {tugas.length === 0 && <p className="kecil">Belum ada tugas. Tambahkan yang pertama!</p>}
      <PilihFilter nilai={filter} onPilih={setFilter} />
      <p className="kecil">
        {sisa} tugas belum selesai{' '}
        {tugas.some((t) => t.selesai) && <button type="button" onClick={hapusSelesai}>Hapus yang selesai</button>}
      </p>
    </div>
  );
}

createRoot(document.getElementById('root')).render(
  <StrictMode>
    <App />
  </StrictMode>
);

